// ===== 채울 값: 토큰만 붙여넣기 (IG_USER_ID 는 채워둠) =====
const ACCESS_TOKEN = 'PASTE_INSTAGRAM_ACCESS_TOKEN';
const IG_USER_ID = '27545798328443881';
// =======================================================
const G = 'https://graph.instagram.com';
const ME = G + '/' + IG_USER_ID;
const b = $input.first().json.body;
const jobId = b.jobId;
const caption = (b.payload && b.payload.caption) || '';
const images = (b.payload && b.payload.images) || [];
let step = 'start';

// 모든 호출이 IG 실제 에러 본문을 throw 하도록 (returnFullResponse + ignoreHttpStatusErrors)
const call = async (method, url, params) => {
  const res = await this.helpers.httpRequest({
    method, url,
    qs: Object.assign({}, params, { access_token: ACCESS_TOKEN }),
    json: true, returnFullResponse: true, ignoreHttpStatusErrors: true,
  });
  if (res.statusCode >= 300) throw new Error('HTTP ' + res.statusCode + ' ' + JSON.stringify(res.body));
  return res.body;
};
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

try {
  // 1) 이미지별 캐러셀 아이템 컨테이너
  const ids = [];
  for (let i = 0; i < images.length; i++) {
    step = 'item' + i;
    const r = await call('POST', ME + '/media', { image_url: images[i], is_carousel_item: 'true' });
    ids.push(r.id);
  }
  // 2) 캐러셀 컨테이너
  step = 'carousel';
  const c = await call('POST', ME + '/media', { media_type: 'CAROUSEL', children: ids.join(','), caption: caption });
  // 3) 컨테이너 FINISHED 까지 폴링 (안 하면 media_publish 가 400)
  step = 'wait';
  for (let t = 0; t < 15; t++) {
    const s = await call('GET', G + '/' + c.id, { fields: 'status_code' });
    if (s.status_code === 'FINISHED') break;
    if (s.status_code === 'ERROR' || s.status_code === 'EXPIRED') throw new Error('container ' + s.status_code);
    await sleep(2500);
  }
  // 4) 발행
  step = 'publish';
  const p = await call('POST', ME + '/media_publish', { creation_id: c.id });
  return [{ json: { jobId, status: 'published', externalRef: String(p.id) } }];
} catch (e) {
  return [{ json: { jobId, status: 'failed', error: ('[' + step + '] ' + ((e && e.message) || String(e))).slice(0, 800) } }];
}

// 백엔드 콜백 바디를 '문자열'로 고정 → HMAC 서명한 바이트 = 보낼 바이트 일치 보장
const j = $input.first().json;
const out = { jobId: j.jobId, status: j.status };
if (j.externalRef) out.externalRef = j.externalRef;
if (j.error) out.error = j.error;
return [{ json: { bodyString: JSON.stringify(out) } }];
